import{_t as e,it as t,n,rt as r}from"./chunks/framework.CNKdcd3j.js";import"./chunks/assets.vG9Ybq_z.js";var i=JSON.parse(`{"title":"Presets","description":"","frontmatter":{},"headers":[],"relativePath":"presets.md","filePath":"presets.md"}`),a={name:`presets.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="presets" tabindex="-1">Presets <a class="header-anchor" href="#presets" aria-label="Permalink to “Presets”">​</a></h1><p>kle-ng ships a library of ready-made layouts — full-size ANSI and ISO, 60% variants, ortholinear, split and ergonomic boards, and a blank canvas.</p><img src="/docs/preset-library-light.png" class="docs-screenshot light-only" alt="Import from Preset dialog showing a grid of layout cards"><img src="/docs/preset-library-dark.png" class="docs-screenshot dark-only" alt="Import from Preset dialog showing a grid of layout cards"><p>The most popular presets are listed directly in the <strong>Import</strong> menu under <strong>Top Presets</strong>. <strong>Import → From Preset</strong> opens the whole library. Search by name or keyword (<code>ortho</code>, <code>split</code>, <code>60%</code>) and click a card to load it.</p><p>Loading a preset replaces the current layout and clears the undo history, so save your work first.</p><h2 id="languages" tabindex="-1">Languages <a class="header-anchor" href="#languages" aria-label="Permalink to “Languages”">​</a></h2><p><strong>ANSI 104</strong>, <strong>ISO 105</strong>, <strong>Default 60%</strong> and <strong>ISO 60%</strong> come in 117 languages. The legends follow the layouts shipped with X11, including AltGr characters.</p><img src="/docs/preset-language-menu-light.png" class="docs-screenshot light-only" alt="Language menu of the ANSI 104 card with Polish highlighted" style="max-width:320px;"><img src="/docs/preset-language-menu-dark.png" class="docs-screenshot dark-only" alt="Language menu of the ANSI 104 card with Polish highlighted" style="max-width:320px;"><p>To pick a language, click the globe button in the card&#39;s corner (<code>🌐 EN</code>) and choose one from the list, then click the card to load it. Clicking the card without opening the list loads the default language. You can type in the list to jump to a language by name or code, for example <code>pol</code> or <code>pl</code> for Polish.</p><p>The default is US English on every board, kept plain with only the base and Shift legends. For a UK printing, choose <strong>British English</strong>. For more legends, choose <strong>English (US, International)</strong> or <strong>British English (Extended)</strong>, which add the AltGr layer. For Japanese, <strong>Japanese (Kana)</strong> adds kana next to the romaji.</p><p>Some languages also offer alternative layouts, listed next to the language under the same name: <strong>English (Dvorak)</strong>, <strong>English (Colemak)</strong> and <strong>English (Colemak-DH)</strong>; <strong>French (BÉPO)</strong> and the newer <strong>French (AZERTY, AFNOR)</strong> standard; <strong>German (E1)</strong> and <strong>German (Neo 2)</strong>; the QWERTY versions of Czech and Slovak; <strong>Turkish (F)</strong>; <strong>Romanian (Standard)</strong>; the phonetic Russian and Bulgarian layouts; <strong>Tamil (Tamil99)</strong>; and <strong>Canadian French (Multilingual)</strong>.</p><img src="/docs/preset-ansi-104-polish-light.png" class="docs-screenshot light-only" alt="ANSI 104 preset loaded in Polish"><img src="/docs/preset-ansi-104-polish-dark.png" class="docs-screenshot dark-only" alt="ANSI 104 preset loaded in Polish"><h3 id="reading-the-legends" tabindex="-1">Reading the legends <a class="header-anchor" href="#reading-the-legends" aria-label="Permalink to “Reading the legends”">​</a></h3><img src="/docs/preset-legend-corners-light.png" class="docs-screenshot light-only" alt="Polish 2 key with four legends: @, 2, ¿ and ²" style="max-width:120px;float:right;margin-left:16px;"><img src="/docs/preset-legend-corners-dark.png" class="docs-screenshot dark-only" alt="Polish 2 key with four legends: @, 2, ¿ and ²" style="max-width:120px;float:right;margin-left:16px;"><p>A key can show up to four characters, one in each corner. The Polish <code>2</code> key on the right shows all four:</p><table tabindex="0"><thead><tr><th>Corner</th><th>How to type it</th><th>Example</th></tr></thead><tbody><tr><td>Bottom left</td><td>the key alone</td><td><code>2</code></td></tr><tr><td>Top left</td><td><kbd>Shift</kbd></td><td><code>@</code></td></tr><tr><td>Bottom right</td><td><kbd>AltGr</kbd></td><td><code>²</code></td></tr><tr><td>Top right</td><td><kbd>Shift</kbd> + <kbd>AltGr</kbd></td><td><code>¿</code></td></tr></tbody></table><p>Letter keys show only the capital letter, as printed keycaps do. The letter is typed in lower case, or in upper case with <kbd>Shift</kbd>. The same goes for a capital on the right: on the Polish <code>A</code> key, <code>Ą</code> means <kbd>AltGr</kbd> types <code>ą</code> and <kbd>Shift</kbd> + <kbd>AltGr</kbd> types <code>Ą</code>.</p><p><strong>Japanese (Kana)</strong> is the exception: its right-hand corners show kana instead of AltGr characters.</p><img src="/docs/preset-dead-key-light.png" class="docs-screenshot light-only" alt="German ^ key: the circumflex dead key drawn on a dotted circle, with °, ″ and ′" style="max-width:120px;float:right;margin-left:16px;"><img src="/docs/preset-dead-key-dark.png" class="docs-screenshot dark-only" alt="German ^ key: the circumflex dead key drawn on a dotted circle, with °, ″ and ′" style="max-width:120px;float:right;margin-left:16px;"><p>Dead keys are drawn with their accent on a dotted circle (◌), so you can tell them apart from ordinary characters such as <code>^</code>. A dead key types nothing by itself; it adds its accent to the next letter you type. On the German <code>^</code> key on the right, the circumflex in the bottom-left corner is a dead key; the other three characters are not.</p><p>The language only affects the legends; the key positions are the same in every language. It is not saved in the layout, but it becomes part of the default file name (<code>ansi-104-pl</code>).</p>`,26)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};